import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ userName, userId, handleLogout }) {
  const [activeMenu, setActiveMenu] = useState('Dashboard');
  const [studentInfo, setStudentInfo] = useState({
    name: userName || 'Student',
    regNo: userId || 'AP/ST/2026/01',
    course: 'Grade 6 - Core Package'
  });

  // 🌐 ඩේටාබේස් එකෙන් ලොග් වුණු ශිෂ්‍යයාගේ ඇත්තම තොරතුරු ඇදලා ගැනීම
  useEffect(() => {
    if (userId) {
      axios.get(`http://localhost:8081/api/student-profile/${userId}`)
        .then(res => {
          if (res.data) {
            setStudentInfo({
              name: res.data.name,
              regNo: res.data.registration_no,
              course: res.data.course || 'Grade 6 - Core Package'
            });
          }
        })
        .catch(err => console.error("Error fetching student live profile:", err));
    }
  }, [userId, userName]);

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 AURA PEN GREEN SIDEBAR SECTION */}
      <div style={{ width: '260px', backgroundColor: '#15803d', color: '#fff', display: 'flex', flexDirection: 'column', padding: '20px 0', boxShadow: '4px 0 10px rgba(0,0,0,0.05)' }}>
        
        {/* 🖼️ LOGO SECTION (ඔයාගේ Aura Pen Logo එක මෙතනට වැටෙනවා) */}
        <div style={{ padding: '0 20px 25px 20px', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ width: '45px', height: '45px', backgroundColor: '#fff', borderRadius: '8px', display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '2px' }}>
            <img 
              src="/logo.png" // 💡 ඔයාගේ public ෆෝල්ඩර් එකේ තියෙන ලෝගෝ එකේ නම 'logo.png' නම් මේක ඉබේම වැඩ කරයි
              onError={(e) => { e.target.src = "🖋️" }} // ලෝගෝ එක නැත්නම් පෑනක ලකුණක් වැටේ
              alt="Aura Pen Logo" 
              style={{ width: '100%', height: '100%', objectFit: 'contain' }}
            />
          </div>
          <div>
            <h2 style={{ margin: 0, color: '#fff', fontSize: '18px', fontWeight: '800', letterSpacing: '0.5px' }}>AURA PEN</h2>
            <span style={{ fontSize: '10px', color: '#dcfce7', opacity: 0.9, fontWeight: '700' }}>STUDENT LMS PORTAL</span>
          </div>
        </div>

        {/* මෙනු බටන්ස් ටික */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '3px' }}>
          {[
            { id: 'Dashboard', label: '📊 Dashboard' },
            { id: 'My Subjects', label: '📚 My Subjects' },
            { id: 'Online Quizzes', label: '📝 Online Quizzes' },
            { id: 'Quiz Results', label: '🏆 Quiz Results' },
            { id: 'Notifications', label: '🔔 Notifications' },
            { id: 'Discussion Forum', label: '💬 Discussion Forum' },
            { id: 'Feedback', label: '⭐ Feedback' },
            { id: 'My Profile', label: '👤 My Profile' }
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveMenu(item.id)}
              style={{
                width: '100%', padding: '13px 20px', border: 'none',
                backgroundColor: activeMenu === item.id ? '#166534' : 'transparent',
                color: '#fff', fontSize: '14px', fontWeight: '600', cursor: 'pointer',
                textAlign: 'left', transition: '0.2s', borderLeft: activeMenu === item.id ? '5px solid #38bdf8' : '5px solid transparent'
              }}
            >
              {item.label}
            </button>
          ))}
        </div>

        {/* Logout බටන් එක */}
        <div style={{ padding: '0 20px' }}>
          <button onClick={handleLogout} style={{ width: '100%', backgroundColor: 'transparent', border: '1px solid rgba(255,255,255,0.4)', color: '#fff', padding: '11px', borderRadius: '8px', fontWeight: '700', cursor: 'pointer', transition: '0.2s' }}>
            🚪 Logout
          </button>
        </div>
      </div>

      {/* ⚪ MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '35px', overflowY: 'auto' }}>
        
        {/* Welcome Banner (ලොග් වුණු ළමයාගේ නම සහ Reg No එක ඩේටාබේස් එකෙන්මයි පේන්නේ) */}
        <div style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.01)', border: '1px solid #e2e8f0', borderLeft: '6px solid #15803d', marginBottom: '30px' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '26px', fontWeight: '800' }}>
            👋 Welcome, {studentInfo.name}
          </h2>
          <p style={{ margin: '6px 0 0 0', color: '#64748b', fontSize: '14px', fontWeight: '600' }}>
